export type WorkflowSplitStage = 'macro' | 'meso' | 'micro';
declare const WORKFLOW_PROMPT_POLICY_CATALOG: {
    readonly protocolOutputContract: readonly ["只返回严格 JSON；禁止输出 markdown、解释、前后缀说明。", "最终 JSON 必须同时包含 `macroSplit`、`mesoSplit`、`microSplit`、`actions`。", "`allowedOps` 只能是 `reuse` / `modify` / `create_child`。", "`macroSplit`、`mesoSplit`、`microSplit` 应显式保留当前 triadization focus 与 recommendedOperation，三者不得漂移。", "`macroSplit` 负责寻找挂载点，并拆出左分支=子功能、右分支=编排 / 配置。", "`mesoSplit` 负责把子功能继续拆成类与数据管道。", "`microSplit` 负责把类继续拆成属性 / 状态与方法 / 动作，并明确 demand / answer。", "`actions` 是最终可 apply 的落地协议；可复用则优先 `reuse`，可局部升级则 `modify`，只有无法稳定挂载时才 `create_child`。", "`create_child` 必须提供 `parentNodeId`，并保持符合顶点三元法的最小裂变。"];
    readonly implementationExecutionWorkflow: readonly ["1. 先锁定当前 triadization focus；后续所有拆分都必须围绕同一个目标节点与同一个 recommendedOperation。", "2. 再执行 Macro-Split：寻找挂载点，并把功能拆成左分支=子功能、右分支=编排 / 配置。", "3. 再执行 Meso-Split：把子功能继续拆成类（Class）、数据管道（Pipeline）与职责边界。", "4. 最后执行 Micro-Split：把类拆成属性 / 状态（静态右分支）与方法 / 动作（动态左分支）。", "5. 把三轮结果折叠进最终 `draft-protocol.json`，再进入 visualizer 审核。", "6. 协议确认之后，才允许继续具体实现。"];
    readonly masterPromptStageRouter: readonly ["1. 只有当 `actions` 非空时，Draft / Approved Protocol 才算完成。", "2. 只有当 `macroSplit` 出现 `anchorNodeId`，或 `leftBranch` / `rightBranch` 非空时，才算完成 Macro-Split。", "3. 只有当 `mesoSplit` 的 `classes` 或 `pipelines` 非空时，才算完成 Meso-Split。", "4. 只有当 `microSplit.classes` 非空，且类中存在属性 / 方法拆分时，才算完成 Micro-Split。", "5. Draft / Approved Protocol 是否生效，要以 `userDemand` 是否匹配当前最新需求为准。", "6. 若 Approved Protocol 已完成且需求匹配，则进入实现阶段。", "7. 若 Draft Protocol 已完成且需求匹配，但尚未批准，则先走 visualizer 审核。", "8. 若 Micro 已完成但 Draft 未完成，则汇总最终 `draft-protocol.json`。", "9. 若 Meso 已完成但 Micro 未完成，则继续 Micro-Split。", "10. 若 Macro 已完成但 Meso 未完成，则继续 Meso-Split。", "11. 若以上都未完成，则先做 Macro-Split。", "12. 若实现阶段发现协议无法承载需求，应停止编码并返回协议阶段。"];
    readonly masterPromptProtocolPhase: readonly ["先锁定并引用当前 triadization focus；没有确认焦点时，不要擅自漂移到其他节点。", "先做 Macro-Split：挂载点 + 左分支子功能 + 右分支编排 / 配置。", "再做 Meso-Split：类与数据管道。", "最后做 Micro-Split：属性 / 状态 + 方法 / 动作。", "最终输出必须汇总成严格 JSON 的 `draft-protocol.json`。"];
    readonly masterPromptImplementationPhase: readonly ["优先依据 Approved Protocol JSON 与 Changed Skeleton Files 完善代码。", "严格在已批准节点职责内实现，不要擅自新增拓扑分支。", "若存在 `implementation-handoff.md`，优先服从它。"];
    readonly masterPromptExpectedBehavior: readonly ["先判断阶段，再执行对应子任务。", "协议阶段：先给协议，再等待 visualizer / 用户确认。", "实现阶段：先给简洁实现计划，再补全代码实现。"];
    readonly implementationHandoffRules: readonly ["1. 不要重新发明拓扑；默认协议与 triad-map 已批准。", "2. 只在批准后的节点职责范围内补全实现，不要绕开节点边界随意扩散。", "3. 优先完善当前骨架文件，必要时再补其直接依赖。", "4. 如果发现实现困难，先检查是否能通过 reuse 已存在能力解决，而不是新增节点。", "5. 如果实现确实要求拓扑改变，应停止编码并返回协议阶段。"];
    readonly implementationOutputRules: readonly ["先指出当前建议三元化的节点，以及推荐动作是 aggregate / split / renormalize 中的哪一种。", "先确认这个建议，再进入 Macro / Meso / Micro 三轮拆分。", "Macro / Meso / Micro 三轮结果必须显式保留同一个 `triadizationFocus` 与 `recommendedOperation`，不能静默切换。", "先给出 Macro / Meso / Micro 三轮拆分结果。", "再给出 `draft-protocol.json` 的严格 JSON 内容。", "再给出简洁实现计划。", "如果当前就在编码环境中工作，应先把协议写入 `.triadmind/draft-protocol.json`。", "如果协议尚未确认，就停在协议阶段，不要跳过 visualizer 审核。"];
    readonly pipelineDiagnosis: readonly ["先指出当前建议三元化的节点，以及推荐动作是 aggregate / split / renormalize 中的哪一种。", "先确认该建议，再进入 Macro-Split。"];
    readonly pipelineRules: readonly ["每一轮都必须继承上一轮，不能跳步。", "如果上层拆分不稳定，就不能进入下层。", "如果发现需要切换到其他节点或其他动作，必须先停止当前推演并返回 triadization 确认。", "最终协议必须包含 `macroSplit`、`mesoSplit`、`microSplit`、`actions`。"];
    readonly implementationExpectedOutput: readonly ["先给出简洁实现计划。", "然后基于现有骨架代码完成实现。", "完成后总结修改了哪些文件，以及这些修改如何对应已批准协议。"];
};
